91:  include Attachmentable # Load prior to Avatar & Header concerns
93:  include Account::Associations
94:  include Account::Avatar
95:  include Account::Counters
96:  include Account::FaspConcern
97:  include Account::FinderConcern
98:  include Account::Header
99:  include Account::InteractionPolicyConcern
100:  include Account::Interactions
101:  include Account::Mappings
102:  include Account::Merging
103:  include Account::Search
104:  include Account::Sensitizes
105:  include Account::Silences
106:  include Account::StatusesSearch
107:  include Account::Suspensions
108:  include Account::AttributionDomains
109:  include DomainMaterializable
110:  include DomainNormalizable
111:  include Paginable
112:  include Reviewable
118:  validates :username, presence: true
119:  validates_with UniqueUsernameValidator, if: -> { will_save_change_to_username? }
122:  validates :username, format: { with: USERNAME_ONLY_RE }, length: { maximum: USERNAME_LENGTH_HARD_LIMIT }, if: -> { (remote? || actor_type_application?) && will_save_change_to_username? }
125:  validates :uri, presence: true, unless: :local?, on: :create
128:  validates :username, format: { with: /\A[a-z0-9_]+\z/i }, length: { maximum: USERNAME_LENGTH_LIMIT }, if: -> { local? && will_save_change_to_username? && !actor_type_application? }
129:  validates_with UnreservedUsernameValidator, if: -> { local? && will_save_change_to_username? && !actor_type_application? && !user&.bypass_registration_checks }
130:  validates :display_name, length: { maximum: DISPLAY_NAME_LENGTH_LIMIT }, if: -> { local? && will_save_change_to_display_name? }
131:  validates :note, note_length: { maximum: NOTE_LENGTH_LIMIT }, if: -> { local? && will_save_change_to_note? }
132:  validates :fields, length: { maximum: DEFAULT_FIELDS_SIZE }, if: -> { local? && will_save_change_to_fields? }
133:  validates_with EmptyProfileFieldNamesValidator, if: -> { local? && will_save_change_to_fields? }
142:  validates :domain, exclusion: { in: [''] }
146:  scope :without_internal, -> { where(id: 1...) }
147:  scope :remote, -> { where.not(domain: nil) }
148:  scope :local, -> { where(domain: nil) }
149:  scope :partitioned, -> { order(Arel.sql('row_number() over (partition by domain)')) }
150:  scope :without_instance_actor, -> { where.not(id: INSTANCE_ACTOR_ID) }
151:  scope :recent, -> { reorder(id: :desc) }
152:  scope :non_automated, -> { where.not(actor_type: AUTOMATED_ACTOR_TYPES) }
153:  scope :matches_uri_prefix, ->(value) { where(arel_table[:uri].matches("#{sanitize_sql_like(value)}/%", false, true)).or(where(uri: value)) }
154:  scope :matches_username, ->(value) { where('lower((username)::text) LIKE lower(?)', "#{value}%") }
155:  scope :matches_display_name, ->(value) { where(arel_table[:display_name].matches("#{value}%")) }
156:  scope :without_unapproved, -> { left_outer_joins(:user).merge(User.approved.confirmed).or(remote) }
157:  scope :auditable, -> { where(id: Admin::ActionLog.select(:account_id).distinct) }
158:  scope :searchable, -> { without_unapproved.without_suspended.where(moved_to_account_id: nil) }
159:  scope :discoverable, -> { searchable.without_silenced.where(discoverable: true).joins(:account_stat) }
160:  scope :by_recent_status, -> { includes(:account_stat).merge(AccountStat.by_recent_status).references(:account_stat) }
161:  scope :by_recent_activity, -> { left_joins(:user, :account_stat).order(coalesced_activity_timestamps.desc).order(id: :desc) }
162:  scope :by_domain_and_subdomains, ->(domain) { where(domain: Instance.by_domain_and_subdomains(domain).select(:domain)) }
163:  scope :not_excluded_by_account, ->(account) { where.not(id: account.excluded_from_timeline_account_ids) }
164:  scope :not_domain_blocked_by_account, ->(account) { where(arel_table[:domain].eq(nil).or(arel_table[:domain].not_in(account.excluded_from_timeline_domains))) }
165:  scope :dormant, -> { joins(:account_stat).merge(AccountStat.without_recent_activity) }
166:  scope :with_username, ->(value) { value.is_a?(Array) ? where(arel_table[:username].lower.in(value.map { |x| x.to_s.downcase })) : where(arel_table[:username].lower.eq(value.to_s.downcase)) }
167:  scope :with_domain, ->(value) { where arel_table[:domain].lower.eq(value&.to_s&.downcase) }
168:  scope :without_memorial, -> { where(memorial: false) }
169:  scope :duplicate_uris, -> { select(:uri, Arel.star.count).group(:uri).having(Arel.star.count.gt(1)) }
